function box(parent,x,y,z,w,h,d,color){const geometry=new THREE.BoxGeometry(w,h,d);ownedGeometries.add(geometry);const mesh=new THREE.Mesh(geometry,mat(color));mesh.position.set(x,y,z);mesh.castShadow=h>.15;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
