function textSurface(text,color,w,parent,x,y,z,flat=true,bg=null){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=flat?128:384;const ctx=canvas.getContext('2d');if(bg){ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height)}ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';let size=flat?90:94;do{ctx.font=`800 ${size}px Arial`;size-=2}while(ctx.measureText(text).width>950&&size>16);ctx.fillText(text,512,canvas.height/2);const texture=new THREE.CanvasTexture(canvas);ownedTextures.add(texture);texture.colorSpace=THREE.SRGBColorSpace;const geometry=new THREE.PlaneGeometry(w,w*canvas.height/1024),material=new THREE.MeshBasicMaterial({map:texture,transparent:!bg,depthWrite:!!bg,side:THREE.DoubleSide});ownedGeometries.add(geometry);ownedMaterials.add(material);const mesh=new THREE.Mesh(geometry,material);if(flat)mesh.rotation.x=-Math.PI/2;mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
