function bridge(x,z,length,across=false,cable=false){const g=new THREE.Group();g.position.set(x,0,z);if(across)g.rotation.y=Math.PI/2;world.add(g);box(g,0,.29,0,.52,.13,length,'#a1a7ab');for(const side of [-1,1]){box(g,side*.3,.43,0,.045,.13,length,'#c5c8ca');for(let i=-length/2+.25;i<length/2;i+=.6)cylinder(g,side*.22,-.15,i,.04,.8,'#999e9c');}if(cable){for(let z of [-length*.3,length*.3]){box(g,0,1.5,z,.08,2.5,.08,'#eee6d6');for(let k of [-1,1]){const p=[new THREE.Vector3(0,2.6,z),new THREE.Vector3(0,.4,z+k*length*.35)];g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(p),new THREE.LineBasicMaterial({color:'#e2dfd2'})));}}}return g;}
