const modelPaths=async path=>{if(!modelCache.has(path))modelCache.set(path,Promise.resolve().then(()=>loadModel(path)));return modelCache.get(path)};
async function addModel(parent,path,height,pos=[0,0,0],tint=null,rotation=0){const original=await modelPaths(path);assertAlive();const object=original.clone(true);object.traverse(n=>{n.userData.mapModelAsset=true});object.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true;if(tint){n.material=n.material.clone();ownedMaterials.add(n.material);n.material.color.set(tint)}}});const bounds=new THREE.Box3().setFromObject(object),center=bounds.getCenter(new THREE.Vector3()),factor=height/(bounds.getSize(new THREE.Vector3()).y||1);object.position.set(-center.x,-bounds.min.y,-center.z);const group=new THREE.Group();group.add(object);group.scale.setScalar(factor);group.position.set(...pos);group.rotation.y=rotation;parent.add(group);return group;}
